<?php declare(strict_types=1); namespace Annam; $title='WhatsApp connection'; ?>
<form class="o-form" method="post"><?= csrf() ?><section class="o-card"><p>Secrets are write-only. Leave them blank to keep saved values.</p><label class="o-field">Message provider<select name="wa_provider"><?php foreach(['console'=>'Local testing only','meta_cloud'=>'Meta Cloud API','n8n'=>'n8n automation'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $integration['wa_provider']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><div class="o-grid-form"><?php foreach(['wa_phone_number_id'=>'Meta phone number ID','wa_waba_id'=>'WhatsApp Business Account ID','n8n_send_url'=>'n8n send URL','n8n_receive_url'=>'n8n incoming forwarding URL'] as $key=>$label): ?><label class="o-field"><?= e($label) ?><input name="<?= e($key) ?>" value="<?= e($integration[$key]) ?>"></label><?php endforeach; ?><?php foreach(['wa_token'=>'Meta access token','wa_app_secret'=>'Meta app secret','wa_verify_token'=>'Meta verification token','wa_sync_token'=>'Inbox sync bearer token','n8n_auth_token'=>'n8n bearer token'] as $key=>$label): ?><label class="o-field"><?= e($label) ?><input name="<?= e($key) ?>" type="password" autocomplete="new-password"></label><?php endforeach; ?></div><button class="o-btn o-btn-primary">Save connection</button></section></form><section class="o-card"><h2>Automation endpoints</h2><p>Meta callback: <code><?= e(rtrim(getenv('APP_URL'),'/').'/webhooks/whatsapp/') ?></code></p><p>n8n inbox sync: <code><?= e(rtrim(getenv('APP_URL'),'/').'/webhooks/whatsapp/n8n/') ?></code></p><p>Schedule <code>bin/cron.php</code> every minute to send queued messages, forward incoming events and reconcile payments. Mirrored messages do not automatically become orders. Use Create booking in a conversation.</p></section>
